//! ♻️ Intrinsic history retirement returns every original read and its exact issuer before closing typed entries and bounded native backing.
use super::*;
use semio_framework_value::{RetainedAllocationEffect,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,FactoryAuthority,ArtifactOwnedValueRetirementFactory,FactoryOwnedRetirement,ErasedSnapshotRetirement};
use semio_framework_value::retained_clone::{RetainedCloneClose,retained_clone_grant_admits};
use semio_framework_value::retirement::{RetireOwned,RetirementCursor,RetirementStep};
use std::{mem::{ManuallyDrop,size_of},sync::Arc};
#[doc(hidden)]
pub struct LedgerRetirement<T:RetireOwned>{ledger:ManuallyDrop<Option<ArtifactHistoryLedger<T>>>,payload:ManuallyDrop<Option<T>>,factory:ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<T>>>>,ticket:ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,intrinsic:RetainedCloneClose,authority:Option<FactoryAuthority>,returned:Option<ArtifactHistoryReadKey>}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->Result<RetirementDemand,ValueError>{d.depth=d.depth.checked_add(1).ok_or_else(||ValueError::literal(protocol::value::ValueRefusalKind::DepthLimit,"intrinsic history child depth overflow"))?;Ok(d)}
impl<T:RetireOwned> LedgerRetirement<T>{
 fn demand(&self,body:usize)->Result<RetirementDemand,ValueError>{
  if let Some(ticket)=self.ticket.as_ref(){return nested(semio_framework_value::factory_ticket_demands(ticket,body)?)}
  if !self.intrinsic.is_empty(){return nested(self.intrinsic.next_owner_demands::<T>(false,&None,body)?)}
  if let Some(authority)=self.authority.as_ref(){return if authority.terminal_is_empty(){Ok(header::<Option<FactoryAuthority>>())}else{nested(authority.demands(body)?)}}
  if self.payload.is_some(){return if self.factory.is_some(){nested(RetirementDemand{capacity_bytes:FactoryOwnedRetirement::<T>::constructor_capacity_bytes(),depth:1,..Default::default()})}else{self.intrinsic.next_owner_demands::<T>(true,&None,body)}}
  if let Some(key)=self.returned{if self.factory.is_some(){return Ok(header::<(T,ArtifactHistoryReadKey)>())}return nested(self.ledger.as_ref().ok_or_else(||ValueError::literal(protocol::value::ValueRefusalKind::InvariantViolated,"intrinsic history retirement lost its ledger"))?.retained_read_return_demands(key,body)?)}
  if self.factory.is_some(){return Ok(header::<FactoryAuthority>())}
  if let Some(ledger)=self.ledger.as_ref(){if let Some(demand)=ledger.abandoned_directory_demand(){return Ok(demand)}if ledger.next_retained_read_key().is_some(){return Ok(header::<Option<ArtifactHistoryReadKey>>())}if !ledger.is_empty(){return Ok(header::<T>())}if !ledger.terminal_is_empty(){return Err(ValueError::literal(protocol::value::ValueRefusalKind::OwnershipLimit,"intrinsic history retirement requires its original group decision to settle"))}if ledger.retained_terminal_slot_count()>0{return Ok(header::<Option<Arc<ArtifactGroupVisibility>>>())}return Ok(RetirementDemand{release_bytes:ledger.next_empty_page_release_byte_demand()?,depth:1,..Default::default()})}Ok(Default::default())
 }
 fn empty(&self)->bool{self.ledger.is_none()&&self.payload.is_none()&&self.factory.is_none()&&self.ticket.is_none()&&self.intrinsic.is_empty()&&self.authority.is_none()&&self.returned.is_none()}
 fn step(&mut self,effect:&mut RetainedAllocationEffect<'_>)->Result<RetainedCloneStep,Exit>{
  let g=effect.grant();let d=self.demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()};let child=RetainedCloneGrant{maximum_depth:g.maximum_depth.saturating_sub(1),..g};
  let missing=||ValueError::literal(protocol::value::ValueRefusalKind::InvariantViolated,"intrinsic history retirement lost its ledger");
  if self.ticket.is_some(){return kid(semio_framework_value::close_factory_ticket(&mut self.ticket,&mut effect.nested(child))).map(|step|RetainedCloneStep::Progress(step.progress()))}
  if !self.intrinsic.is_empty(){return kid(self.intrinsic.step_granted(&mut effect.nested(child))).map(|step|RetainedCloneStep::Progress(step.progress()))}
  if let Some(authority)=self.authority.as_mut(){if !authority.terminal_is_empty(){return kid(authority.step(&mut effect.nested(child))).map(|step|RetainedCloneStep::Progress(step.progress()))}Exit::pay(effect,1)?;self.authority=None;return Ok(RetainedCloneStep::Progress(p))}
  if self.payload.is_some(){if self.factory.is_some(){let step=kid_value(FactoryOwnedRetirement::<T>::admit_original(&mut self.payload,&mut self.factory,&mut self.ticket,&mut effect.nested(child)))?;return Ok(RetainedCloneStep::Progress(step.progress()))}return Ok(self.intrinsic.begin_granted(&mut self.payload,effect).result?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}
  if let Some(key)=self.returned{let Some(ledger)=self.ledger.as_mut()else{return Err(missing().into())};if self.factory.is_none(){return Ok(RetainedCloneStep::Progress(ledger.return_retained_read(key,&mut self.factory,&mut effect.nested(child)).result?.progress()))}Exit::pay(effect,1)?;*self.payload=Some(ledger.remove_key(key.key).map_err(|_|ValueError::literal(protocol::value::ValueRefusalKind::InvariantViolated,"returned original history slot changed"))?);self.returned=None;return Ok(RetainedCloneStep::Progress(p))}
  if let Some(factory)=self.factory.take(){Exit::pay(effect,1)?;self.authority=Some(FactoryAuthority::new(factory));return Ok(RetainedCloneStep::Progress(p))}
  if let Some(ledger)=self.ledger.as_mut(){
   if ledger.abandoned_directory_demand().is_some(){let turn=ledger.recover_abandoned_directory(g);let paid=Exit::pay(effect,turn.work);let step=turn.result?;paid?;return Ok(RetainedCloneStep::Progress(step.progress()))}
   if let Some(key)=ledger.next_retained_read_key(){Exit::pay(effect,1)?;self.returned=Some(key);return Ok(RetainedCloneStep::Progress(p))}
   if !ledger.is_empty(){Exit::pay(effect,1)?;let Some(value)=ledger.pop()else{return Err(missing().into())};*self.payload=Some(value);return Ok(RetainedCloneStep::Progress(p))}
   if ledger.retained_terminal_slot_count()>0{Exit::pay(effect,1)?;let(view,mut receipt)=ledger.retire_terminal_slot(g)?;receipt.copied_bytes=d.copy_bytes;if let Some(view)=view{self.authority=Some(FactoryAuthority::new(view))}return Ok(RetainedCloneStep::Progress(receipt))}
   if !ledger.backing_is_empty(){Exit::pay(effect,1)?;return Ok(RetainedCloneStep::Progress(ledger.release_empty_page(g)?.progress()))}
   Exit::pay(effect,1)?;self.ledger.take();return Ok(RetainedCloneStep::Progress(p))}
  Ok(RetainedCloneStep::Complete(Default::default()))
 }
}
type Exit=semio_framework_value::RetirementPollExit;
fn kid(poll:semio_framework_value::OriginalRetirementPoll)->Result<RetainedCloneStep,Exit>{Exit::settled(poll)?.result.map_err(Exit::from)}
fn kid_value(poll:semio_framework_value::RetainedWorkPoll<RetainedCloneStep,ValueError>)->Result<RetainedCloneStep,Exit>{match poll{semio_framework_value::RetainedWorkPoll::Pending{work}=>Err(Exit::Pending(work)),semio_framework_value::RetainedWorkPoll::Complete(turn)=>turn.result.map_err(Exit::from)}}
impl<T:RetireOwned> RetireOwned for ArtifactHistoryLedger<T>{type RetirementCursor=LedgerRetirement<T>;fn retirement_seed(self)->Self::RetirementCursor{LedgerRetirement{ledger:ManuallyDrop::new(Some(self)),payload:ManuallyDrop::new(None),factory:ManuallyDrop::new(None),ticket:ManuallyDrop::new(None),intrinsic:Default::default(),authority:None,returned:None}}fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<LedgerRetirement<T>>())}fn controlled_retirement_supported()->bool{T::controlled_retirement_supported()}}
impl<T:RetireOwned> RetirementCursor for LedgerRetirement<T>{fn next_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{self.demand(b)}fn close_step(&mut self,effect:&mut RetainedAllocationEffect<'_>)->RetirementStep{let result=self.step(effect);let work=effect.performed_work();match result{Ok(RetainedCloneStep::Complete(p))if p==Default::default()=>RetirementStep::Complete(work),Ok(step)=>RetirementStep::Progress(step.progress(),work),Err(Exit::Pending(_))=>RetirementStep::Pending(work),Err(Exit::Failed(failure))=>RetirementStep::Failure(failure,work)}}fn terminal_is_empty(&self)->bool{self.empty()}fn terminal_release_bytes(&self)->Option<usize>{self.empty().then_some(size_of::<Self>())}}
impl<T:RetireOwned> Drop for LedgerRetirement<T>{fn drop(&mut self){assert!(self.empty()||std::thread::panicking(),"intrinsic history retirement retains original slots and issuers until funded terminal closure");if self.empty(){unsafe{ManuallyDrop::drop(&mut self.ledger);ManuallyDrop::drop(&mut self.payload);ManuallyDrop::drop(&mut self.factory);ManuallyDrop::drop(&mut self.ticket);}}}}

#[cfg(test)]
mod tests{
 use super::*;
 use semio_framework_value::retirement::controlled::ControlledRetirement;
 fn observe<T>(call:impl FnOnce()->T)->(T,usize,usize){let(value,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(call);(value,h.requested_bytes,h.released_bytes)}
 static ORIGINAL:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
 #[derive(semio_framework_value::FactoryPayloadRetirement)]
 struct Issuer;
 impl ArtifactOwnedValueRetirementFactory<String> for Issuer{fn retire_owned_work_demand(&self,_:&String)->Result<u64,semio_framework_value::ValueError>{Ok(1)}fn retirement_birth_bytes(&self,_:&String)->usize{semio_framework_value::owned_retirement_birth_bytes::<String>()}fn retire_owned(&self,original:String,g:RetainedCloneGrant)->semio_framework_value::RetainedWorkOutcome<(Box<dyn ErasedSnapshotRetirement>,RetainedCloneProgress),(semio_framework_value::OriginalRetirementFailure,String)>{let turn=(||{ORIGINAL.store(original.as_ptr()as usize,std::sync::atomic::Ordering::Relaxed);semio_framework_value::admit_owned_retirement(original,g)})();semio_framework_value::RetainedWorkOutcome{result:turn.result.map_err(|(error,value)|(error.into(),value)),work:turn.work}}}
 fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes+d.capacity_bytes<=4096,"original history body {:?}",d);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
 #[test]
 fn original_abandoned_directory_pin_returns_inside_intrinsic_retirement(){let mut ledger=ArtifactHistoryLedger::new();ledger.try_push(7u32).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:ArtifactHistoryDirectoryCursor::<u32>::copy_bytes(),maximum_depth:1,..Default::default()};let caught=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let mut cursor=None;assert!(ArtifactHistoryDirectoryCursor::admit_tail(&mut ledger,1,g,&mut cursor).result.unwrap().0);panic!("cancel original directory turn")}));assert!(caught.is_err());assert!(ledger.abandoned_directory_demand().is_some());let mut retirement=ControlledRetirement::new(ledger).ok().unwrap();let mut work=0u64;for _ in 0..10000{if retirement.terminal_is_empty(){break}let d=retirement.next_demand(4096).unwrap();let step=retirement.step(grant(d)).unwrap();work+=retirement.last_turn_work();assert!(step.progress().fits(grant(d)));}assert!(retirement.terminal_is_empty());assert!(work>0);}
 #[test]
 fn original_intrinsic_ledger_returns_same_read_issuer_and_waits_for_owning_projection(){for prefix in [0,1,2]{ORIGINAL.store(0,std::sync::atomic::Ordering::Relaxed);let mut ledger=ArtifactHistoryLedger::empty();let d=ledger.initial_page_birth_demand().unwrap();let(p,a,r)=observe(||ledger.admit_initial_page(grant(d)).unwrap());assert_eq!((a,r),(p.retained_capacity_bytes,p.released_bytes));let original="actual native α".repeat(1024);let pointer=original.as_ptr()as usize;let key=ledger.try_push(original).ok().unwrap();let key=ledger.retained_read_key(key).unwrap();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(Issuer);let advances=match prefix{0=>0,1=>1,_=>10000};let mut advanced=0;while advanced<advances{let d=ledger.retained_read_demands(key).unwrap();let turn=ledger.advance_retained_read(key,&factory,grant(d));let work=turn.work;let step=turn.result.unwrap();if step.progress()!=RetainedCloneProgress::default(){assert!(work>0)}advanced+=1;if matches!(step,semio_framework_value::retained_clone::RetainedCloneStep::Complete(_)){break;}}assert!(prefix<2||advanced<advances,"original read birth did not complete");let mut projection=if prefix==2{let d=semio_framework_value::RetainedOwnedProjection::<String>::constructor_demand();{let turn=ledger.retain_read(key,grant(d));assert!(turn.work>0);Some(turn.result.unwrap().0)}}else{None};let mut close=ControlledRetirement::new(ledger).ok().unwrap();for turn in 0..10000{if turn==5{if let Some(read)=projection.as_mut(){while !read.terminal_is_empty(){let d=read.close_demand(4096).unwrap();let(step,a,r)=observe(||read.close_step(grant(d)).result.unwrap());assert_eq!((a,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}}projection=None;}if close.terminal_is_empty(){break}let d=close.next_demand(4096).unwrap();let(step,a,r)=observe(||close.step(grant(d)).unwrap());assert_eq!((a,r),(step.progress().retained_capacity_bytes,step.progress().released_bytes));if projection.is_some(){assert_eq!(ORIGINAL.load(std::sync::atomic::Ordering::Relaxed),0);}assert!(turn<9999);}assert!(close.terminal_is_empty());assert_eq!(ORIGINAL.load(std::sync::atomic::Ordering::Relaxed),if prefix==0{0}else{pointer});}}
}
